// Regenerates the embedded copy of the config-only apps (browser bundles have no fs): packages/haunt/src/config/embedded-apps.ts.
// Usage: npm run apps:embed            rewrite the copy
//        npm run apps:embed -- --check exit 1 when the copy has drifted (never hand edit the generated file)
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
/** Same list as BUNDLED_APP_DIRS in packages/haunt/src/config/bundled-apps.ts (a test keeps them equal). */
export const APP_DIRS = ['apps/haunted-playback', 'examples/coffee-shop'];

export function renderApps(apps) {
  const body = Object.entries(apps).map(([dir, text]) => `  ${JSON.stringify(dir)}: ${JSON.stringify(text.split('\r\n').join('\n'))},`).join('\n');
  return `// GENERATED by tools/embed-apps.mjs from the haunt.yaml of each config-only app. Do not edit: run \`npm run apps:embed\`.\n` +
    `// A drift test fails when this copy differs from the files.\n` +
    `export const EMBEDDED_APPS: Readonly<Record<string, string>> = {\n${body}\n};\n`;
}

export function readApps(base = root) {
  const out = {};
  for (const d of APP_DIRS) { const f = resolve(base, d, 'haunt.yaml'); if (existsSync(f)) out[d] = readFileSync(f, 'utf8'); }
  return out;
}

export function embedApps({ check = false, base = root } = {}) {
  const out = resolve(base, 'packages/haunt/src/config/embedded-apps.ts');
  const want = renderApps(readApps(base));
  const have = existsSync(out) ? readFileSync(out, 'utf8') : '';
  if (have === want) return [];
  if (!check) writeFileSync(out, want);
  return [out];
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const check = process.argv.includes('--check');
  const changed = embedApps({ check });
  if (check && changed.length) { console.error('embedded apps are out of date; run: npm run apps:embed'); process.exit(1); }
  console.log(changed.length ? 'rewrote packages/haunt/src/config/embedded-apps.ts' : 'embedded apps are up to date');
}
